-- Authenticator-app MFA (TOTP, RFC 6238 -- Google Authenticator, Microsoft Authenticator,
-- 1Password, ...) offered ALONGSIDE the existing email-code MFA (202609080001).
--
-- public.mfa_factors stays the single "MFA is enabled" record that the session gate,
-- sign-in and get_my_mfa_status already read, so none of those change. It gains a
-- `method`: 'email' (codes emailed, the original behaviour) or 'totp' (codes from an
-- authenticator app).
--
-- The TOTP secret is generated by the app, shown once as a QR code / setup key, and
-- stored here encrypted (private.encrypt_sensitive_field, the KYC-field key). Codes are
-- checked inside Postgres with pgcrypto's HMAC, so the secret is never read back out.
--
-- An authenticator account can NOT be sent an emailed code: create_mfa_challenge refuses
-- 'verify' for method 'totp'. Otherwise the password plus the inbox would bypass the app,
-- making it no stronger than email. Its fallback is backup codes, as before.

alter table public.mfa_factors
  add column method text not null default 'email' check (method in ('email', 'totp')),
  add column totp_secret_encrypted bytea,
  -- The last accepted 30-second step: a code is never accepted twice (replay).
  add column totp_last_step bigint,
  -- Wrong-code throttle: at most 5 failures per 15 minutes.
  add column totp_failures int not null default 0,
  add column totp_failure_window_start timestamptz;

-- RFC 6238 / RFC 4226: HMAC-SHA1 of the 8-byte big-endian step, dynamic truncation,
-- 6 digits.
create or replace function private.totp_code(p_key bytea, p_step bigint)
returns text
language plpgsql immutable
as $$
declare
  h bytea := extensions.hmac(int8send(p_step), p_key, 'sha1');
  o int := get_byte(h, 19) & 15;
  bin bigint;
begin
  bin := ((get_byte(h, o) & 127)::bigint << 24) | (get_byte(h, o + 1)::bigint << 16) | (get_byte(h, o + 2)::bigint << 8) | get_byte(h, o + 3)::bigint;
  return lpad((bin % 1000000)::text, 6, '0');
end;
$$;

revoke all on function private.totp_code(bytea, bigint) from public;

-- ---------------------------------------------------------------------------
-- begin_my_totp_enrollment -- stores a new, unverified authenticator secret (hex) for the
-- actor. Refused while MFA is already enabled: disable first, then switch methods.
-- ---------------------------------------------------------------------------
create or replace function public.begin_my_totp_enrollment(p_secret_hex text)
returns void
language plpgsql security definer set search_path = ''
as $$
declare actor uuid := auth.uid();
begin
  if actor is null then raise exception 'AUTH_REQUIRED: authentication required' using errcode = '28000'; end if;
  if p_secret_hex !~ '^[0-9a-f]{40}$' then raise exception 'INVALID_INPUT: malformed secret' using errcode = '22023'; end if;
  if exists (select 1 from public.mfa_factors f where f.user_id = actor and f.status = 'verified') then
    raise exception 'ALREADY_ENROLLED: two-factor authentication is already enabled' using errcode = '42710';
  end if;

  delete from public.mfa_challenges where user_id = actor;
  insert into public.mfa_factors (user_id, status, method, totp_secret_encrypted, totp_last_step, totp_failures, totp_failure_window_start)
    values (actor, 'unverified', 'totp', private.encrypt_sensitive_field(p_secret_hex), null, 0, null)
    on conflict (user_id) do update set
      status = 'unverified', verified_at = null, method = 'totp',
      totp_secret_encrypted = excluded.totp_secret_encrypted,
      totp_last_step = null, totp_failures = 0, totp_failure_window_start = null;
end;
$$;

revoke all on function public.begin_my_totp_enrollment(text) from public;
grant execute on function public.begin_my_totp_enrollment(text) to authenticated;

-- ---------------------------------------------------------------------------
-- verify_my_totp_code -- checks a 6-digit code against the actor's authenticator secret,
-- allowing one 30-second step of clock drift either way. Returns 'enroll' (first code:
-- the factor is now verified), 'verify' (sign-in check passed), 'invalid', or
-- 'rate_limited'. Like verify_mfa_challenge it never RAISEs for a wrong code -- a RAISE
-- would roll back the failure counter it just incremented.
-- ---------------------------------------------------------------------------
create or replace function public.verify_my_totp_code(p_code text)
returns text
language plpgsql security definer set search_path = ''
as $$
declare
  actor uuid := auth.uid();
  factor public.mfa_factors;
  key bytea;
  now_step bigint := floor(extract(epoch from now()) / 30)::bigint;
  matched bigint;
begin
  if actor is null then raise exception 'AUTH_REQUIRED: authentication required' using errcode = '28000'; end if;

  select * into factor from public.mfa_factors f where f.user_id = actor and f.method = 'totp' for update;
  if factor.user_id is null or factor.totp_secret_encrypted is null then
    raise exception 'NOT_ENROLLED: no authenticator app is set up' using errcode = '22023';
  end if;

  if factor.totp_failure_window_start is null or factor.totp_failure_window_start < now() - interval '15 minutes' then
    factor.totp_failures := 0;
    factor.totp_failure_window_start := now();
  end if;
  if factor.totp_failures >= 5 then
    return 'rate_limited';
  end if;

  if p_code ~ '^\d{6}$' then
    key := decode(private.decrypt_sensitive_field(factor.totp_secret_encrypted), 'hex');
    select s into matched
      from unnest(array[now_step - 1, now_step, now_step + 1]) as s
      where private.totp_code(key, s) = p_code and s > coalesce(factor.totp_last_step, -1)
      order by s
      limit 1;
  end if;

  if matched is null then
    update public.mfa_factors
      set totp_failures = factor.totp_failures + 1, totp_failure_window_start = factor.totp_failure_window_start
      where user_id = actor;
    return 'invalid';
  end if;

  update public.mfa_factors
    set totp_last_step = matched, totp_failures = 0, totp_failure_window_start = null,
        status = 'verified', verified_at = coalesce(verified_at, now())
    where user_id = actor;
  return case when factor.status = 'verified' then 'verify' else 'enroll' end;
end;
$$;

revoke all on function public.verify_my_totp_code(text) from public;
grant execute on function public.verify_my_totp_code(text) to authenticated;

-- ---------------------------------------------------------------------------
-- create_mfa_challenge -- unchanged except: (1) starting EMAIL enrollment resets the
-- factor to method 'email' and drops any authenticator secret, and (2) an emailed
-- 'verify' code is refused for an authenticator account (see header).
-- ---------------------------------------------------------------------------
create or replace function public.create_mfa_challenge(p_purpose text, p_code_hash text, p_ttl_seconds integer)
returns uuid
language plpgsql security definer set search_path = ''
as $$
declare
  actor uuid := auth.uid();
  has_verified_factor boolean;
  factor_method text;
  recent_count integer;
  new_id uuid;
begin
  if actor is null then raise exception 'AUTH_REQUIRED: authentication required' using errcode = '28000'; end if;
  if p_purpose not in ('enroll', 'verify') then raise exception 'INVALID_PURPOSE: unrecognized challenge purpose' using errcode = '22023'; end if;

  select exists(select 1 from public.mfa_factors f where f.user_id = actor and f.status = 'verified') into has_verified_factor;
  select f.method into factor_method from public.mfa_factors f where f.user_id = actor;
  if p_purpose = 'enroll' and has_verified_factor then
    raise exception 'ALREADY_ENROLLED: two-factor authentication is already enabled' using errcode = '42710';
  end if;
  if p_purpose = 'verify' and not has_verified_factor then
    raise exception 'NOT_ENROLLED: two-factor authentication is not enabled' using errcode = '22023';
  end if;
  if p_purpose = 'verify' and factor_method = 'totp' then
    raise exception 'TOTP_METHOD: use the code from your authenticator app' using errcode = '22023';
  end if;

  select count(*) into recent_count
    from public.mfa_challenges
    where user_id = actor and purpose = p_purpose and created_at > now() - interval '15 minutes';
  if recent_count >= 5 then
    raise exception 'RATE_LIMITED: too many codes requested. Wait a few minutes and try again.' using errcode = '42901';
  end if;

  update public.mfa_challenges set consumed_at = now()
    where user_id = actor and purpose = p_purpose and consumed_at is null;

  insert into public.mfa_challenges (user_id, purpose, code_hash, expires_at)
    values (actor, p_purpose, p_code_hash, now() + make_interval(secs => p_ttl_seconds))
    returning id into new_id;

  if p_purpose = 'enroll' then
    insert into public.mfa_factors (user_id, status, method) values (actor, 'unverified', 'email')
      on conflict (user_id) do update set
        status = 'unverified', verified_at = null, method = 'email',
        totp_secret_encrypted = null, totp_last_step = null, totp_failures = 0, totp_failure_window_start = null;
  end if;

  return new_id;
end;
$$;

revoke all on function public.create_mfa_challenge(text, text, integer) from public;
grant execute on function public.create_mfa_challenge(text, text, integer) to authenticated;

-- list_my_mfa_factors gains `method` (a changed return type needs drop + create).
drop function public.list_my_mfa_factors();
create function public.list_my_mfa_factors()
returns table (id uuid, status text, created_at timestamptz, method text)
language plpgsql stable security definer set search_path = ''
as $$
declare actor uuid := auth.uid();
begin
  if actor is null then raise exception 'AUTH_REQUIRED: authentication required' using errcode = '28000'; end if;
  return query select f.user_id, f.status, f.created_at, f.method from public.mfa_factors f where f.user_id = actor;
end;
$$;

revoke all on function public.list_my_mfa_factors() from public;
grant execute on function public.list_my_mfa_factors() to authenticated;
